/**
 * Charge Explanation Jurisdiction Overlay
 *
 * Per-state structured detail for shared/charge-explanations.ts entries. Separate from that
 * file for the same reason shared/criminal-charge-citations.ts is separate from
 * criminal-charges.ts: this grows to full 56-jurisdiction coverage over many sessions and
 * should not require touching the base explanation content to add a state.
 *
 * Every entry here is grounded in statute text actually read at the given sourceUrl (a state
 * legislature or official government site), not general knowledge or template inference. See
 * SOURCES.md for the full methodology and coverage status.
 *
 * Confidence levels:
 *   'high'   : real statute text read directly from the official state legislature/government
 *              site (sourceUrl points to that page)
 *   'medium' : statute text read from a reliable secondary source (e.g. Justia mirror) when the
 *              official site was unreachable
 *   'low'    : citation confirmed but full text not yet independently read. Do not treat keyRule
 *              as verified until promoted
 *
 * How to add an entry:
 *   1. Look up the citation in shared/criminal-charge-citations.ts (key: "{state}-{slug}").
 *      The citation research is almost always already done there.
 *   2. Read the actual statute text at that citation's sourceUrl.
 *   3. Write a 1-3 sentence keyRule describing what actually makes this state's version of the
 *      charge distinct (the legal test used, degree/terminology, a key threshold), not a
 *      restatement of the charge name.
 *   4. Set dataConfidence and lastVerified (YYYY-MM) honestly. Leave penaltyClass absent rather
 *      than guess if the fetched text didn't include it.
 */

export interface JurisdictionChargeDetail {
  /** Full citation in standard legal format, e.g. "Va. Code Ann. § 18.2-32" */
  citation: string;
  /** 1-3 sentences: what makes this state's version of the charge distinct */
  keyRule: string;
  /** e.g. "Class 2 felony". Only set when confirmed from real fetched statute text */
  penaltyClass?: string;
  /** Human-readable source name, e.g. "California Legislative Information" */
  source: string;
  sourceUrl?: string;
  dataConfidence: 'high' | 'medium' | 'low';
  /** YYYY-MM */
  lastVerified: string;
}

/**
 * Keyed `{state}-{slug}`, matching the shared/criminal-charge-citations.ts convention exactly
 * (slug is the ChargeExplanation.slug field in shared/charge-explanations.ts).
 * e.g. "ny-murder-in-the-first-degree"
 */
