    keyRule: "Voluntary manslaughter requires knowingly causing a death while under sudden passion or rage brought on by serious provocation from the victim, reasonably sufficient to incite deadly force (a first degree felony). Involuntary manslaughter requires causing death as a proximate result of committing or attempting a felony (first degree felony) or certain misdemeanors (third degree felony).",
    source: "Ohio Laws and Rules (codes.ohio.gov)",
    sourceUrl: "https://codes.ohio.gov/ohio-revised-code/section-2903.03",
    dataConfidence: "high",
    lastVerified: "2026-08",
