    keyRule: "Illinois has no separate voluntary manslaughter statute. A heat-of-passion killing is charged as second degree murder instead. Involuntary manslaughter requires unintentionally killing someone through reckless acts likely to cause death or great bodily harm; it becomes a more serious felony if the victim is a family or household member. Deaths caused by driving are charged separately as reckless homicide.",
    penaltyClass: "Class 3 felony (involuntary manslaughter); Class 2 felony if the victim is a family or household member",
