    keyRule: "Voluntary manslaughter requires circumstances that would otherwise be murder, but the killing resulted solely from sudden, violent, irresistible passion from serious provocation, without enough time for reason to prevail. Involuntary manslaughter has two tiers: causing a death during an unlawful act that is not a felony (a felony, 1 to 10 years), or causing a death through a lawful act performed in a dangerous, unlawful manner (only a misdemeanor).",
    penaltyClass: "1 to 20 years (voluntary); 1 to 10 years or misdemeanor depending on the tier (involuntary)",
