    keyRule: "A single statute covers several distinct ways to commit manslaughter: recklessly causing a death, a heat-of-passion killing that would otherwise be second degree murder, intentionally assisting an adult's suicide, committing what would be second degree murder while coerced by threat of deadly force, and recklessly causing an unborn child's death through injury to the mother.",
    penaltyClass: "Class 2 felony",
