    keyRule: "Covers impairment 'to the slightest degree,' a notably strict standard, a 0.08% BAC threshold (0.04% for commercial and for-hire/rideshare drivers), and a zero-tolerance rule for any amount of certain drugs or their metabolites in your body.",
    source: "Arizona State Legislature (azleg.gov)",
    sourceUrl: "https://www.azleg.gov/ars/28/01381.htm",
    dataConfidence: "high",
    lastVerified: "2026-08",
