    keyRule: "Theft covers unauthorized control over property, obtaining property by deception or threat, or knowingly receiving stolen property, with intent to permanently deprive the owner. Property not taken from a person and valued at $500 or less is a Class A misdemeanor. Above $500, or theft from a person at any value, becomes a Class 3 felony, scaling up through Class 2, Class 1, a non-probationable Class 1, and Class X felony as the value increases past $1,000,000. Theft from a school, place of worship, or of government property is enhanced by at least one class.",
