    keyRule: "Theft is unlawfully appropriating property with intent to deprive the owner of it, without the owner's effective consent. Texas has an unusually granular value ladder: under $100 is a Class C misdemeanor, $100 to $749 a Class B misdemeanor, $750 to $2,499 a Class A misdemeanor, $2,500 to $29,999 a state jail felony, $30,000 to $149,999 a third degree felony, $150,000 to $299,999 a second degree felony, and $300,000 or more a first degree felony. Offenses are enhanced one category higher if the victim was elderly or disabled, or was a nonprofit organization.",
