    keyRule: "Theft by unlawful taking is unlawfully taking, or exercising unlawful control over, another's movable property with intent to deprive them of it. Pennsylvania's felony threshold is $2,000 for ordinary theft, but a lower $200 threshold applies to theft from a person, by threat, or in breach of a fiduciary duty. Below the felony line, three separate misdemeanor tiers apply by value: under $50, $50 to under $200, and the general under-$2,000 tier. Above $2,000 it becomes a third degree felony, rising to second degree at $100,000 and first degree at $500,000. Amounts from multiple thefts under a single scheme can be added together to reach a higher grade.",
