    keyRule: "Michigan's manslaughter statute is unusually bare: it states only that manslaughter is a felony and sets the penalty, without defining the offense or splitting it into voluntary and involuntary tiers in the statute text itself. The elements and any heat-of-passion or recklessness distinction come from case law and jury instructions, not the statute.",
