    keyRule: "Michigan does not use 'first degree assault.' Its closest equivalent, and most serious non-lethal assault charge, is assaulting someone with intent to do great bodily harm less than murder, or assaulting someone by strangulation or suffocation (intentionally impeding normal breathing or blood circulation by pressure on the throat or neck, or blocking the nose or mouth). Both paths carry the same penalty.",
