    keyRule: "First degree murder covers a premeditated intent to cause death, acting with extreme indifference to human life through conduct creating a grave risk of death, or the felony murder rule limited to a specific enumerated list: first or second degree robbery, rape, arson, or kidnapping, or first degree burglary. A participant who was unarmed, uninvolved in the killing itself, and had no reason to believe others were armed or intended deadly conduct may raise an affirmative defense.",
    penaltyClass: "Class A felony",
    source: "Washington State Legislature (app.leg.wa.gov)",
