    keyRule: "Washington splits felony murder across two degrees rather than treating it as one rule. Killing someone during a limited, enumerated list of felonies (first or second degree robbery, rape, arson, or kidnapping, or first degree burglary) is first degree murder. A death during any other felony, including ordinary assault, is instead second degree murder under a separate, broader felony murder provision in RCW 9A.32.050.",
