    keyRule: "Washington is a significant outlier on drug possession following the state supreme court's 2021 Blake decision: simple possession of a controlled substance, or using one in public, is a flat gross misdemeanor with no scaling by drug schedule or quantity at all, a marked contrast to the felony, weight-tiered approach most other states surveyed here use. Only a third or later offense (with two or more qualifying priors after July 2023) raises the maximum jail term, still within the same misdemeanor-level classification. Adult cannabis possession within legal limits is exempted entirely.",
