    keyRule: "Tennessee's base burglary statute explicitly excludes habitations: it covers entering (or remaining concealed in, or committing a crime in) a building other than a habitation, or a vehicle, with intent to commit a felony, theft, or assault. No breaking is required, entry alone with the required intent is enough. Burglary of a habitation is instead charged separately as 'aggravated burglary,' a use of the word 'aggravated' to mean 'of a dwelling' rather than the weapon- or injury-based meaning it has in most other Tennessee statutes.",
