    keyRule: "Voluntary manslaughter is what would otherwise be second degree murder, but committed under the influence of sudden passion arising from adequate cause (the defendant bears the burden of raising this), or knowingly assisting another's self-murder. Missouri's involuntary manslaughter, confusingly labeled 'first degree' even though it is the less serious homicide charge, is simply recklessly causing a death.",
