    keyRule: "Wisconsin does not use 'manslaughter' as a charge name at all. What other states call voluntary manslaughter is handled entirely within the intentional homicide statutes as a mitigating-circumstance reduction from first to second degree, not a separate charge. What other states call involuntary manslaughter is called second degree reckless homicide here: recklessly causing a death, meaning the defendant was subjectively aware of an unreasonable, substantial risk of death or great bodily harm and disregarded it.",
    penaltyClass: "Class D felony",
    source: "Wisconsin State Legislature (docs.legis.wisconsin.gov)",
