    keyRule: "Knowingly possessing a controlled substance without a valid prescription, with the penalty scaled by the specific drug rather than a uniform schedule: heroin and methamphetamine are a flat felony regardless of amount; cocaine, and hallucinogens or stimulants like LSD, PCP, or MDMA, are a lesser fine-or-jail offense on a first violation but escalate to a felony on any later one; THC/marijuana is the lightest tier, fine or up to 6 months on a first offense, felony on a repeat; and GHB, ketamine, and flunitrazepam are a flat felony regardless of quantity.",
    penaltyClass: "Fine and/or up to 6 months (THC, first offense); fine and/or up to 1 year in county jail (cocaine, hallucinogens/stimulants, first offense); Class I felony (heroin, methamphetamine, or any repeat offense); Class H felony (GHB, ketamine, flunitrazepam, regardless of amount)",
