    penaltyClass: "Class 4 felony",
    source: "OpenLaws / Colorado Revised Statutes (static.openlaws.us)",
    sourceUrl: "https://static.openlaws.us/laws/co/stat/title_18/article_3/part_1/section_18_3_104",
    dataConfidence: "high",
