    citation: "Colo. Rev. Stat. § 18-4-202 (first degree); § 18-4-203 (second degree)",
    keyRule: "Burglary is knowingly entering unlawfully, or remaining unlawfully after any entry, in a building or occupied structure with intent to commit a crime inside; no breaking is required. It is first degree if, during entry, occupancy, or flight, the offender or another participant assaults or menaces someone, is armed with explosives, or uses or threatens a deadly weapon. Second degree burglary covers the same unlawful-entry conduct (or, alternatively, an actual breaking) without those aggravating factors, graded by the type of structure: occupied structures and commercial buildings are one tier, dwellings and burglaries targeting controlled substances or firearms are more serious, and other buildings are less serious.",
