    penaltyClass: "Up to 20 years and/or a $30,000 fine (base, or deadly force against an official); up to 25 years and/or a $35,000 fine (great bodily harm to an official); up to 30 years and/or a $40,000 fine (deadly force with a weapon causing great bodily harm to an official)",
