    keyRule: "Unlike most states surveyed, Minnesota has a genuine standalone domestic assault crime: intentionally causing fear of imminent bodily harm or death, or intentionally inflicting or attempting to inflict bodily harm, against a qualifying family or household member. A first offense is a misdemeanor, escalating to a gross misdemeanor with one qualifying prior conviction within 10 years, and to a felony with two or more qualifying priors within 10 years. A conviction also triggers mandatory firearm transfer, forfeiture, and possession restrictions.",
