    keyRule: "Covers a 0.08% BAC threshold (0.04% for commercial drivers) or general impairment by alcohol, a controlled substance, cannabis, or a combination. Minnesota's degree numbering is easy to misread: unlike most numbered offense schemes, the least serious, most common first-offense charge is called 'fourth degree' driving while impaired, with first, second, and third degree reserved for progressively more aggravated versions (prior convictions, high BAC, or a child passenger), not the base offense.",
