    keyRule: "Covers operating or being in physical control of a vehicle while intoxicated or under the influence of alcohol or any drug. A first offense is up to $1,000/180 days, with mandatory minimums stacking on top at high BAC tiers (10 days at .20+ blood/breath or .25+ urine, up to 20 days at .30+/.39+, or 15 days if certain drugs like PCP or cocaine are present). A second offense rises to $2,500-$5,000/1 year with a 10-day base mandatory minimum plus BAC-tiered add-ons up to 25 additional days; a third or subsequent offense reaches $2,500-$10,000/1 year with a 15-day base mandatory minimum, similar BAC-tiered add-ons, and a mandatory 5-year license revocation if within the past 5 years.",
