    keyRule: "A hate crime is committing a specified offense while intentionally selecting the victim, in whole or in part, because of race, color, national origin, ancestry, gender, gender identity or expression, religion, religious practice, age, disability, or sexual orientation (the demographics of the defendant or victim alone, without more, cannot prove this). The enhancement bumps a misdemeanor or Class C/D/E felony up one full category; for Class B felonies it raises the mandatory minimum to 6-12 years depending on sentencing type; for Class A-I felonies the minimum rises to at least 20 years; and if the underlying offense itself qualifies as a violent felony, the hate crime is automatically reclassified as a violent felony too. Courts must also generally order hate-crime prevention counseling or training.",
