    keyRule: "New York has a genuinely graduated four-degree arson ladder. The base fourth-degree tier is unusually reckless-only rather than intentional: recklessly damaging a building or motor vehicle by intentionally starting a fire or causing an explosion, a Class E felony, with an affirmative defense if only the defendant had any ownership interest in the property. The top, first-degree tier requires an incendiary device, an explosive, or a fire/explosion causing serious injury to a non-participant or set with an expectation of financial gain, PLUS a non-participant present (known or reasonably foreseeable) in the structure, a Class A-I felony.",
