    keyRule: "Covers a willful failure to appear by someone released under Florida's bail statutes (Chapter 903), graded directly off the underlying case rather than off the failure to appear itself: pending on a felony charge, awaiting sentencing, or awaiting certiorari review after a felony conviction makes the failure a third degree felony, while a misdemeanor-case release makes it a first degree misdemeanor. The offense also triggers forfeiture of any bail security independent of the criminal penalty, and courts retain separate contempt power.",
