    keyRule: "Grades primarily by dollar damage in three clean tiers, from $200 up to the $1,000 felony line, but layers on several fact-specific escalations independent of value: a prior criminal mischief conviction reclassifies a lower tier up to a straight third degree felony, damaging a place of worship or religious article above $200 is automatically a third degree felony, and graffiti carries its own separate mandatory fine and 40-hour community service requirement plus a driver's license sanction for minors, on top of whatever tier the dollar damage otherwise triggers.",
