    keyRule: "Base trespass, willfully entering or remaining in a structure or conveyance without authorization or after being warned to leave, is a second degree misdemeanor, escalating to a first degree misdemeanor if another person was actually present inside at the time. Being armed with a firearm or other dangerous weapon during the trespass elevates the offense all the way to a third degree felony. Property owners and their agents have an explicit statutory right to detain a suspected violator for a reasonable time when they reasonably believe a weapons violation occurred, provided law enforcement is contacted promptly.",
