    keyRule: "Base stalking, willfully, maliciously, and repeatedly following, harassing, or cyberstalking another person, is a first degree misdemeanor. It escalates to aggravated stalking, a third degree felony, when accompanied by a credible threat, when it violates an existing injunction or protective order, when the victim is under 16, or when it follows a conviction for a sexual offense that already prohibits contact with the victim. Cyberstalking is explicitly defined to include unauthorized electronic communication or unauthorized access to someone's online accounts, and courts can issue contact-restraining orders lasting up to 10 years.",
