    citation: "Fla. Stat. § 828.12",
    keyRule: "Base cruelty, overloading, overdriving, tormenting, depriving of necessary sustenance or shelter, or unnecessarily mutilating or killing an animal, is a first degree misdemeanor up to $5,000. It escalates to aggravated animal cruelty, a third degree felony up to $10,000, for intentional acts causing a cruel death or excessive, repeated suffering. Proven knowing and intentional torture that injures, mutilates, or kills the animal carries its own mandatory minimum $2,500 fine plus court-ordered psychological counseling or anger management, and a second or subsequent conviction carries a mandatory minimum $5,000 fine and 6 months actually served with no early release. Horse-tripping is its own standalone third degree felony.",
