    keyRule: "Requires three elements: a willful failure to provide support, an actual present ability to provide it, and knowledge of the legal support obligation (an existing court order alone satisfies the knowledge element). A first through third violation is a first degree misdemeanor; a fourth or subsequent violation, or any violation where more than a year's support totaling $5,000 or more is owed, escalates to a third degree felony. Courts must order restitution for the full unpaid support obligation as it stands at sentencing, and the statute states its purpose is to reach cases where civil enforcement alone has failed to produce payment.",
