    keyRule: "Prohibits firearm, ammunition, stun-weapon, and explosive possession by three groups: anyone convicted of a felony, juveniles 14 or older adjudicated delinquent for specified serious offenses (murder, kidnapping, armed robbery, and rape among them), and people under 29 adjudicated delinquent for a felony-level act. The base offense is a Class 6 felony, but a prior VIOLENT felony triggers a mandatory minimum 5-year sentence, and any other prior felony within the past 10 years triggers a mandatory minimum 2 years, both required to run consecutively to any other sentence. A person can petition the circuit court to restore firearm rights once civil rights have been restored by the Governor.",
