    keyRule: "Virginia bundles resisting arrest into a broader obstruction-of-justice statute covering several distinct acts rather than a single offense. Simple resisting arrest, fleeing once an officer has applied physical force or otherwise communicated arrest authority the person knows or should know they aren't free to leave, is a Class 1 misdemeanor, the same level as basic obstruction, intimidation of a justice-system participant, or knowingly making a materially false statement to an officer during an investigation. Threatening bodily harm or using force against a justice-system participant specifically in connection with a drug, weapons, or violent-felony case escalates that particular conduct to a Class 5 felony.",
