    keyRule: "Unlike Florida's organized-retail-crime-oriented statute, Virginia's shoplifting law is a straightforward concealment-or-price-tampering offense: willfully concealing or taking possession of store merchandise, altering price tags, transferring goods between containers, or aiding another in doing so, all with intent to avoid paying full price or to defraud the owner. The statute builds in a significant evidentiary shortcut: willful concealment of goods while still on the store's premises is itself prima facie evidence of intent to steal, shifting practical weight onto the defendant. Grading follows the general larceny value line rather than a shoplifting-specific threshold.",
