  "va-hate-crime-enhancement": {
    citation: "Va. Code Ann. § 18.2-57 (bias-motivated assault and battery)",
    keyRule: "Virginia is a genuine structural outlier here: unlike every other anchor state sourced so far, it has no general, standalone, cross-offense hate-crime enhancement statute. Bias-motivated treatment is instead built directly into individual offense statutes; the clearest example found is the assault and battery statute itself, where simple assault motivated by the victim's race, religious conviction, gender, disability, gender identity, sexual orientation, color, or national or ethnic origin carries the same misdemeanor classification as ordinary assault but adds a mandatory minimum six months confinement, and bias-motivated assault and battery causing bodily injury is bumped a full level up to a felony with the same six-month mandatory minimum. Virginia's hate-crime protection is narrower and offense-specific rather than a general enhancement layered onto any crime, unlike California, New York, and Florida's approach.",
    penaltyClass: "Class 1 misdemeanor with a mandatory minimum 6 months (bias-motivated simple assault); Class 6 felony with a mandatory minimum 6 months (bias-motivated assault and battery causing bodily injury); offense-specific, not a general enhancement statute",
    source: "Code of Virginia (official statute text)",
    sourceUrl: "https://law.lis.virginia.gov/vacode/18.2-57/",
    dataConfidence: "medium",
    lastVerified: "2026-08",
  },
  "va-kidnapping": {
    citation: "Va. Code Ann. § 18.2-47 (abduction)",
    keyRule: "Virginia calls this offense 'abduction': seizing, taking, transporting, detaining, or secreting another person by force, intimidation, or deception, without legal justification, with intent to deprive them of liberty or conceal them from lawful authority. The statute also separately criminalizes obtaining someone's labor through force, intimidation, or deception, and expands 'intimidation' in that labor-trafficking context to explicitly include threatening to withhold someone's immigration documents, report them as unlawfully present, or separate them from family. Abduction of a minor is a Class 2 felony, more serious than general abduction's Class 5 felony, but a special carve-out exists when a parent or custodial family member removes a child from Virginia in violation of a custody order: that specific scenario is only a Class 6 felony (plus contempt), or just a Class 1 misdemeanor if the child never actually left the state.",
    penaltyClass: "Class 2 felony (abduction of a minor); Class 5 felony (general abduction); Class 6 felony or Class 1 misdemeanor (custodial parent/family-member removal, depending on whether the child left Virginia)",
    source: "Code of Virginia (official statute text)",
    sourceUrl: "https://law.lis.virginia.gov/vacode/18.2-47/",
    dataConfidence: "high",
    lastVerified: "2026-08",
  },
  "va-arson": {
    citation: "Va. Code Ann. § 18.2-77",
    keyRule: "Grades primarily by occupancy rather than by a numbered degree the way most states label it: maliciously burning or destroying an OCCUPIED dwelling, manufactured home, hotel, hospital, mental health facility, railroad car, boat, vessel, jail, prison, or church is a felony carrying imprisonment for life or not less than five years plus up to a $100,000 fine, one of the harshest floor-to-ceiling ranges among the states surveyed. The identical conduct against an UNOCCUPIED version of those same structures drops all the way down to a Class 4 felony. The statute also reaches anyone who aids, counsels, or procures the burning, and anyone who sets fire to an object that in turn causes the listed structure to burn.",
    penaltyClass: "Felony, 5 years to life and up to $100,000 fine (occupied structure); Class 4 felony (unoccupied structure)",
    source: "Code of Virginia (official statute text)",
    sourceUrl: "https://law.lis.virginia.gov/vacode/18.2-77/",
    dataConfidence: "high",
    lastVerified: "2026-08",
  },
  "va-carjacking": {
    citation: "Va. Code Ann. § 18.2-58.1",
    keyRule: "Virginia does have its own standalone carjacking statute, unlike New York (which prosecutes the same conduct as ordinary robbery). Intentional seizure or control of another's motor vehicle with intent to deprive the owner, accomplished through partial strangulation or suffocation, striking or other violence, assault or putting the victim in fear of serious bodily harm, or the threat or display of a firearm or other deadly weapon, is a felony carrying life imprisonment or a mandatory minimum of not less than fifteen years, one of the harshest carjacking floors among the states surveyed, and notably does not vary by whether a weapon was actually used, similar to Florida's approach. The statute expressly does not bar separate prosecution under other applicable Virginia criminal laws for the same conduct.",
    penaltyClass: "Felony, mandatory minimum 15 years up to life",
    source: "Code of Virginia (official statute text)",
    sourceUrl: "https://law.lis.virginia.gov/vacode/18.2-58.1/",
    dataConfidence: "high",
    lastVerified: "2026-08",
  },
  "va-vehicular-homicide": {
    citation: "Va. Code Ann. § 18.2-36.1",
    keyRule: "Like California, Virginia's vehicular-homicide-equivalent offense is tied specifically to impaired driving: unintentionally causing a death while driving under the influence in violation of Virginia's DUI statute is involuntary manslaughter under this section, a felony. It escalates to an aggravated tier, imprisonment of not less than one nor more than 20 years with a mandatory minimum of one year, when the defendant's conduct was so gross, wanton, and culpable as to show a reckless disregard for human life, a heightened-recklessness standard layered on top of the DUI element rather than a fully separate offense. A conviction under either tier triggers mandatory driver's license revocation, and the statute expressly preserves the option to prosecute under other homicide statutes instead.",
    penaltyClass: "Felony (base, specific range not detailed in this section); 1 to 20 years with a 1-year mandatory minimum (aggravated, gross/wanton/culpable disregard for human life)",
    source: "Code of Virginia (official statute text)",
    sourceUrl: "https://law.lis.virginia.gov/vacode/18.2-36.1/",
    dataConfidence: "high",
    lastVerified: "2026-08",
  },

