    keyRule: "A single flat Class 1 misdemeanor covering willful engagement in prostitution, but North Carolina builds in a genuinely detailed first-offender conditional-discharge track not seen with this much structure in most other states surveyed: 12 months of probation with mandatory conditions (no weapons possession, drug testing at least three times, a vocational assessment, and at least 10 counseling sessions), and successful completion results in the case being fully dismissed, made eligible for expunction, and explicitly NOT counted as a conviction for sentencing purposes going forward. Minors are granted outright immunity from prosecution, routed to protective custody with mandatory reporting to social services.",
