    keyRule: "North Carolina builds its consent requirement directly around age: for a victim 16 or older, the victim's own consent controls, but for a victim under 16, the required consent must come from a parent or legal custodian instead, meaning even a nominally 'consenting' younger teen can still be a kidnapping victim if their guardian didn't agree. Grading mirrors Ohio's inverted-incentive structure in spirit: first degree (Class C felony) applies when the victim was NOT released in a safe place or suffered serious injury or sexual assault, while second degree (Class E felony) applies specifically when the victim WAS released safely and unharmed, directly rewarding a safe release the same way Ohio's statute does. A convicted corporate entity faces its own separate fine and charter-forfeiture consequences.",
